class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        long long MOD = 1e9 + 7;
        sort(arr.begin(), arr.end());
        unordered_map<int, long long> dp;
        for (int x : arr) dp[x] = 1;
        int n = arr.size();
        for (int i = 0; i < n; i++) {
            int x = arr[i];
            for (int j = 0; j < i; j++) {
                int y = arr[j];
                if (x % y == 0 && dp.count(x / y)) {
                    dp[x] = (dp[x] + dp[y] * dp[x / y]) % MOD;
                }
            }
        }
        long long total = 0;
        for (const auto& [k, v] : dp) total = (total + v) % MOD;
        return (int)total;
    }
};

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        long MOD = 1_000_000_007L;
        Arrays.sort(arr);
        Map<Integer, Long> dp = new HashMap<>();
        for (int x : arr) dp.put(x, 1L);
        int n = arr.length;
        for (int i = 0; i < n; i++) {
            int x = arr[i];
            for (int j = 0; j < i; j++) {
                int y = arr[j];
                if (x % y == 0 && dp.containsKey(x / y)) {
                    long next = (dp.get(x) + dp.get(y) * dp.get(x / y)) % MOD;
                    dp.put(x, next);
                }
            }
        }
        long total = 0;
        for (long v : dp.values()) total = (total + v) % MOD;
        return (int) total;
    }
}

var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);
    const dp = new Map();
    for (const x of arr) dp.set(x, 1n);
    const n = arr.length;
    for (let i = 0; i < n; i++) {
        const x = arr[i];
        for (let j = 0; j < i; j++) {
            const y = arr[j];
            if (x % y === 0 && dp.has(x / y)) {
                const next = (dp.get(x) + dp.get(y) * dp.get(x / y)) % MOD;
                dp.set(x, next);
            }
